//! An infinite plane.

use crate::aabb::Aabb;
use crate::hittable::{HitRecord, Hittable};
use crate::ray::Ray;
use crate::vec3::Vec3;

/// An infinite plane through `point` with the unit `normal`.
pub struct Plane {
    pub point: Vec3,
    pub normal: Vec3,
}

impl Plane {
    /// Return a plane through `point` with `normal` scaled to unit length.
    pub fn new(point: Vec3, normal: Vec3) -> Self {
        Plane {
            point,
            normal: normal.unit(),
        }
    }
}

impl Hittable for Plane {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let denominator = self.normal.dot(ray.direction);
        if denominator.abs() < 1e-9 {
            return None;
        }
        let t = (self.point - ray.origin).dot(self.normal) / denominator;
        if t <= t_min || t >= t_max {
            return None;
        }
        let point = ray.at(t);
        let (u, v) = if self.normal.x.abs() >= self.normal.y.abs()
            && self.normal.x.abs() >= self.normal.z.abs()
        {
            (point.y, point.z)
        } else if self.normal.y.abs() >= self.normal.z.abs() {
            (point.x, point.z)
        } else {
            (point.x, point.y)
        };
        Some(HitRecord::new(
            ray,
            t,
            point,
            self.normal,
            u.rem_euclid(1.0),
            v.rem_euclid(1.0),
        ))
    }

    /// Return none: an infinite plane has no bounding box.
    fn bounding_box(&self) -> Option<Aabb> {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_ray_hits_the_plane_and_its_texture_coordinates_wrap() {
        let plane = Plane::new(Vec3::new(0.0, -0.5, 0.0), Vec3::new(0.0, 1.0, 0.0));
        let ray = Ray::new(Vec3::new(1.25, 0.0, -0.25), Vec3::new(0.0, -1.0, 0.0));
        let hit = plane.hit(&ray, 0.001, f64::INFINITY).expect("the ray hits");
        assert!((hit.t - 0.5).abs() < 1e-9);
        assert!(hit.front_face);
        assert_eq!(hit.normal, Vec3::new(0.0, 1.0, 0.0));
        assert!((hit.u - 0.25).abs() < 1e-9);
        assert!((hit.v - 0.75).abs() < 1e-9);
    }
}
===TRIANGLE===
//! A triangle.

use crate::aabb::Aabb;
use crate::hittable::{HitRecord, Hittable};
use crate::ray::Ray;
use crate::vec3::Vec3;

/// A triangle with the vertices `a`, `b` and `c` in counter-clockwise order seen from outside.
pub struct Triangle {
    pub a: Vec3,
    pub b: Vec3,
    pub c: Vec3,
}

impl Triangle {
    /// Return a triangle through the three vertices.
    pub fn new(a: Vec3, b: Vec3, c: Vec3) -> Self {
        Triangle { a, b, c }
    }
}

impl Hittable for Triangle {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let edge1 = self.b - self.a;
        let edge2 = self.c - self.a;
        let h = ray.direction.cross(edge2);
        let determinant = edge1.dot(h);
        if determinant.abs() < 1e-8 {
            return None;
        }
        let inverse_determinant = 1.0 / determinant;
        let s = ray.origin - self.a;
        let u = inverse_determinant * s.dot(h);
        if !(0.0..=1.0).contains(&u) {
            return None;
        }
        let q = s.cross(edge1);
        let v = inverse_determinant * ray.direction.dot(q);
        if v < 0.0 || u + v > 1.0 {
            return None;
        }
        let t = inverse_determinant * edge2.dot(q);
        if t <= t_min || t >= t_max {
            return None;
        }
        let outward_normal = edge1.cross(edge2).unit();
        Some(HitRecord::new(ray, t, ray.at(t), outward_normal, u, v))
    }

    /// Return the box that holds the three vertices.
    fn bounding_box(&self) -> Option<Aabb> {
        let min = Vec3::new(
            self.a.x.min(self.b.x).min(self.c.x),
            self.a.y.min(self.b.y).min(self.c.y),
            self.a.z.min(self.b.z).min(self.c.z),
        );
        let max = Vec3::new(
            self.a.x.max(self.b.x).max(self.c.x),
            self.a.y.max(self.b.y).max(self.c.y),
            self.a.z.max(self.b.z).max(self.c.z),
        );
        Some(Aabb::new(min, max))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_ray_through_the_triangle_hits_it_with_barycentric_coordinates() {
        let triangle = Triangle::new(
            Vec3::new(0.0, 0.0, -2.0),
            Vec3::new(1.0, 0.0, -2.0),
            Vec3::new(0.0, 1.0, -2.0),
        );
        let ray = Ray::new(Vec3::new(0.25, 0.25, -1.0), Vec3::new(0.0, 0.0, -1.0));
        let hit = triangle
            .hit(&ray, 0.001, f64::INFINITY)
            .expect("the ray hits");
        assert!((hit.t - 1.0).abs() < 1e-9);
        assert!(hit.front_face);
        assert_eq!(hit.normal, Vec3::new(0.0, 0.0, 1.0));
        assert!((hit.u - 0.25).abs() < 1e-9);
        assert!((hit.v - 0.25).abs() < 1e-9);
    }

    #[test]
    fn a_ray_beside_the_triangle_misses() {
        let triangle = Triangle::new(
            Vec3::new(0.0, 0.0, -2.0),
            Vec3::new(1.0, 0.0, -2.0),
            Vec3::new(0.0, 1.0, -2.0),
        );
        let ray = Ray::new(Vec3::new(2.0, 2.0, -1.0), Vec3::new(0.0, 0.0, -1.0));
        assert!(triangle.hit(&ray, 0.001, f64::INFINITY).is_none());
    }

    #[test]
    fn the_triangle_box_holds_its_three_vertices() {
        let triangle = Triangle::new(
            Vec3::new(-2.0, -0.5, -2.0),
            Vec3::new(2.0, -0.5, -2.0),
            Vec3::new(0.0, 1.5, -2.0),
        );
        let bounds = triangle.bounding_box().expect("the triangle has a box");
        assert_eq!(bounds.min, Vec3::new(-2.0, -0.5, -2.0));
        assert_eq!(bounds.max, Vec3::new(2.0, 1.5, -2.0));
    }
}
